<?php
/** TEMP PS S1610 run e13d — D: deploy petshop-kliento-siuntos.php v1.1 (sargai) + LP plugino nustatymai „Never“; R (init 99): patikra naujame procese + paskyros užsakymų sąrašas kaip klientas 5787 */
add_action('init', function(){
  if (!isset($_GET['ps_e13d'])) return;
  $f=strtoupper(sanitize_key($_GET['ps_e13d'])); $o=array('v'=>'run e13d','f'=>$f); global $wpdb; $p=$wpdb->prefix; set_time_limit(280);
  $o['temp_istrinta']=(int)$wpdb->query("DELETE FROM {$p}snippets WHERE name LIKE 'TEMP%' AND active=0");
  $J=function($o){ header('Content-Type: application/json'); echo json_encode($o,JSON_UNESCAPED_UNICODE|JSON_PARTIAL_OUTPUT_ON_ERROR); exit; };
  try{
  if($f==='D'){
    $up=wp_upload_dir(); $bk=trailingslashit($up['basedir']).'ps-backups'; wp_mkdir_p($bk);
    $k=base64_decode('',true); $o['bytes']=strlen((string)$k); $o['md5']=md5((string)$k);
    if ($o['md5']!=='b13362f1077cd746f9d9e760c29f2942') { $o['STOP']='md5 nesutampa'; $J($o); }
    try { token_get_all($k, TOKEN_PARSE); $o['token']='ok'; } catch (Throwable $e) { $o['STOP']='token: '.$e->getMessage(); $J($o); }
    $kt=WPMU_PLUGIN_DIR.'/petshop-kliento-siuntos.php'; $o['buvo']=md5_file($kt);
    if ($o['buvo']!=='dd636b5c7e69a6af62876810303a91ec') { $o['STOP']='gyvas ne v1.0 ('.$o['buvo'].')'; $J($o); }
    $o['backup']=copy($kt,$bk.'/petshop-kliento-siuntos-v10-BACKUP-'.date('Y-m-d').'.php');
    $o['rasyta']=file_put_contents($kt,$k); $o['po']=md5_file($kt);
    foreach(array('lpsettings_event_to_send_tracking_email','lpsettings_event_to_change_status_to_completed') as $on){ $o['lp_buvo'][$on]=get_option($on); update_option($on,''); $o['lp_po'][$on]=get_option($on); }
  }
  if($f==='R'){
    $o['ks']=Petshop_Kliento_Siuntos::VERSIJA; $o['md5']=md5_file(WPMU_PLUGIN_DIR.'/petshop-kliento-siuntos.php');
    $o['lp_hook_liko']=has_action('woo_lithuaniapost_send_tracking_email');
    global $wp_filter; $o['orders_hookai']=array(); if(!empty($wp_filter['woocommerce_before_account_orders'])){ foreach($wp_filter['woocommerce_before_account_orders']->callbacks as $pr=>$cbs){ foreach($cbs as $cb){ $fn=$cb['function']; $o['orders_hookai'][]=$pr.': '.(is_array($fn)?(is_object($fn[0])?get_class($fn[0]):$fn[0]).'::'.$fn[1]:(is_string($fn)?$fn:'closure')); } } }
    foreach(array('lpsettings_event_to_send_tracking_email','lpsettings_event_to_change_status_to_completed') as $on){ $o['lp'][$on]=get_option($on); }
    if(class_exists('Woo_Lithuaniapost_Admin_Settings')){ $o['lp_get']=array(Woo_Lithuaniapost_Admin_Settings::get_option('event_to_send_tracking_email'),Woo_Lithuaniapost_Admin_Settings::get_option('event_to_change_status_to_completed')); }
    $uid=5787; $exp=time()+1800; $tok=WP_Session_Tokens::get_instance($uid)->create($exp);
    $cs=array(new WP_Http_Cookie(array('name'=>SECURE_AUTH_COOKIE,'value'=>wp_generate_auth_cookie($uid,$exp,'secure_auth',$tok))),new WP_Http_Cookie(array('name'=>AUTH_COOKIE,'value'=>wp_generate_auth_cookie($uid,$exp,'auth',$tok))),new WP_Http_Cookie(array('name'=>LOGGED_IN_COOKIE,'value'=>wp_generate_auth_cookie($uid,$exp,'logged_in',$tok))));
    $u=wc_get_endpoint_url('orders','',wc_get_page_permalink('myaccount')); $r=wp_remote_get($u,array('cookies'=>$cs,'timeout'=>60,'sslverify'=>false)); $b=is_wp_error($r)?'':wp_remote_retrieve_body($r);
    $o['uzsakymai']=array('code'=>is_wp_error($r)?$r->get_error_message():wp_remote_retrieve_response_code($r),'confirm_yra'=>strpos($b,'Confirm your email')!==false,'wc_send_verification'=>strpos($b,'wc_send_verification')!==false,'eiluciu'=>substr_count($b,'woocommerce-orders-table__row'));
    if(preg_match('/<div class="woocommerce-MyAccount-content">(.{0,700})/s',$b,$mm)) $o['uzsakymai']['pradzia']=trim(preg_replace('/\s+/',' ',wp_strip_all_tags($mm[1])));
    $o['cookies']=array(); foreach($cs as $c){ $o['cookies'][]=array('name'=>$c->name,'value'=>$c->value); }
    $o['shots']=array(array('n'=>'e13_uzsakymai','u'=>$u,'full'=>true,'eval'=>"({tekstas:(document.querySelector('.woocommerce-MyAccount-content')||document.body).innerText.replace(/\\s+/g,' ').slice(0,400),notices:[...document.querySelectorAll('.woocommerce-info,.woocommerce-message,.woocommerce-notice')].map(x=>x.innerText.trim())})"));
  }
  }catch(Throwable $e){ $o['FATAL']=$e->getMessage().' @'.$e->getLine(); }
